import java.util.Arrays;
class LibraryMember{protected String memberId;protected int borrowLimit;private int booksBorrowed;private int[] fineHistory=new int[10];private int fineCount;public LibraryMember(String id,int limit){if(id==null||id.trim().length()<4||limit<=0)throw new IllegalArgumentException("Invalid member details");memberId=id;borrowLimit=limit;}public void borrowBook(){if(booksBorrowed<borrowLimit)booksBorrowed++;}public int getBooksBorrowed(){return booksBorrowed;}protected void chargeFine(int n){if(fineCount<fineHistory.length)fineHistory[fineCount++]=n;}public int[] getFineHistory(){return Arrays.copyOf(fineHistory,fineCount);}public int getTotalFine(){int t=0;for(int i=0;i<fineCount;i++)t+=fineHistory[i];return t;}}
class StudentMember extends LibraryMember{private String course;public StudentMember(String id,int l,String c){super(id,l);course=c;}protected void chargeFine(int n){super.chargeFine(n/2);}}
public class FineLedger{public static void main(String[] args){StudentMember s=new StudentMember("STU5",3,"CSE");s.chargeFine(100);System.out.println(s.getTotalFine());int[] h=s.getFineHistory();h[0]=999;System.out.println(Arrays.toString(s.getFineHistory()));}}